const cs=(r,c,v,st)=>`<c r="${L(c)}${r}" s="${st}" t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`,cn=(r,c,v,st)=>`<c r="${L(c)}${r}" s="${st}"><v>${v}</v></c>`,ce=(r,c,st)=>`<c r="${L(c)}${r}" s="${st}"/>`;
