let x=`<row r="1" ht="28" customHeight="1">${cs(1,0,title,1)}</row><row r="2" ht="20" customHeight="1">${cs(2,0,sub,2)}</row><row r="3" ht="32" customHeight="1">${cols.map((c,i)=>cs(3,i,c.h,3)).join('')}</row>`;
rows.forEach((r,i)=>{x+=`<row r="${4+i}">${r.map((v,c)=>{const st=BODY[cols[c].k];return typeof v=='number'?cn(4+i,c,v,st):(v===''||v==null)?ce(4+i,c,st):cs(4+i,c,v,st)}).join('')}</row>`});
const tr=4+n;
if(hasSum)x+=`<row r="${tr}">${cols.map((c,i)=>i==lab?cs(tr,i,'Total',8):c.sum?cn(tr,i,n2(rows.reduce((t,r)=>t+(+r[i]||0),0)),TOT[c.k]):ce(tr,i,8)).join('')}</row>`;
