const pane=fc?`<pane xSplit="${fc}" ySplit="3" topLeftCell="${L(fc)}4" activePane="bottomRight" state="frozen"/><selection pane="topRight"/><selection pane="bottomLeft"/><selection pane="bottomRight"/>`:`<pane ySplit="3" topLeftCell="A4" activePane="bottomLeft" state="frozen"/>`;
